const settings = reactive(createInitialSettings())
const readFailure=ref(null),pendingTicketCheck=ref(null),listsLoaded=ref(false)
let initialized=false
const connection=useServiceConnection(settings,{onRecovered:()=>{if(!busy.value)refreshReadOnly({automatic:true})}})
const {online}=connection
const closurePlan=ref({}),translationLanguages=reactive({}),translationRequests=reactive({})
const composerMode=ref('customer'),noteDraft=ref(''),editingDraftId=ref(''),editedReply=ref(''),memory=ref(null)
const manualOrigin=ref(''),manualDraft=ref(''),operationDraft=ref(''),pendingRequest=ref(null),manualSubmission=ref(null),handoffNote=ref('')
const ticketBaseRevision=ref(1),ticketDraftConflict=ref(false)
let ticketFormKey='',ticketHydrating=true,ticketInitial={}
const handoffLabels={pending:'等待接手',accepted:'已接受',returned:'已退回',cancelled:'已取消'}
const searchMode=ref('business'),importScope=ref('business'),reviewNote=ref('')
const reviewLabels={draft:'草稿',pending:'待审核',approved:'已审核'}
const scopeLabels={test:'测试资料',business:'业务知识'}
const documentDirty=computed(()=>document.value && (editor.title!==document.value.title||editor.content!==document.value.content||editor.scope!==(document.value.scope||'test')))
const demoPolicies=ref([]),demoPolicy=ref(null),demoPolicyDialog=ref(null)
const effectiveDocs=computed(()=>currentSpace.value?.is_demo?demoPolicies.value:docs.value.filter(d=>!d.deleted&&d.scope==='business'&&d.published_version))
const view = ref(['examples','todo','desk','tickets','feedback','knowledge','report','map','team','monitor'].includes(window.location.hash.slice(1))?window.location.hash.slice(1):'todo'), busy = ref(false), notice = ref(''), failed = ref(false)
const conversations = ref([]), selected = ref(null), messages = ref([]), draft = ref(''), queueFilter = ref('all'), queueSearch = ref('')
const tickets = ref([]), ticket = ref(null), ticketEdit = reactive({owner:'',status:'open',note:''})
watch(ticketEdit,()=>{if(ticketHydrating||!ticket.value||!ticketFormKey)return;if(sameForm(ticketEdit,ticketInitial))clearFormDraft(ticketFormKey);else if(!writeFormDraft(ticketFormKey,{fields:copyForm(ticketEdit),base:ticketBaseRevision.value}))inform('浏览器无法保留工单未提交内容，请先保存再离开',true)},{deep:true,flush:'sync'})
function rebaseTicket(){ticketBaseRevision.value=ticket.value.revision||1;ticketDraftConflict.value=false;writeFormDraft(ticketFormKey,{fields:copyForm(ticketEdit),base:ticketBaseRevision.value});inform('工单草稿已保留，请核对当前处理历史后再提交')}
function discardTicketDraft(){clearFormDraft(ticketFormKey);openTicket(ticket.value)}

const workspaces=ref([]),operationsFilter=ref('mine'),workflowRevision=ref(0),followupPanel=ref(null),closureChecks=ref(null)
const currentSpace=computed(()=>workspaces.value.find(w=>w.id===settings.workspaceId))
const members=computed(()=>currentSpace.value?.members||[{id:settings.userId,role:'agent'}])
const intakeDialog=ref(null),closureDialog=ref(null),closureReason=ref(''),closureException=ref(''),rechecksPanel=ref(null)
const intakeDraftNotice=ref('');let intakeDraftKey='',intakeHydrating=true
const closureErrorCaseId=ref('')
const intake=reactive({issue_type:'other',product_id:'',quantity:null,desired_outcome:'',evidence_note:''})
const issueLabels={complaint:'投诉',logistics:'物流',missing:'缺件 / 少件',refund:'退款诉求',account:'账户',other:'其他'}
const intakeLabels={product_id:'涉及商品',quantity:'涉及数量',desired_outcome:'期望结果',evidence_note:'材料说明'}
const imports = ref([])
const docs = ref([]), document = ref(null), editor = reactive({title:'',content:'',version:1,scope:'business'}), includeArchived = ref(false)
const query = ref(''), results = ref([]), searched = ref(false), docDialog = ref(null), newDoc = reactive({title:'',content:'',scope:'business'})
const feedback = ref([]), dataset = ref(null), feedbackQuery = ref(''), order = ref(null), orderQuery = ref(''), orderResults = ref([])
const monitor = ref(null), identityDialog = ref(null), identity = ref(settings.userId), log = ref(null), mobileQueue = ref(false)
const api = (path, method='GET', body) => workbenchRequest(settings,path,method,body)
const userQuery = () => 'user_id='+encodeURIComponent(settings.userId)
const labels = {open:'待处理',pending:'待跟进',in_progress:'处理中',resolved:'已解决'}
const nav = [{id:'examples',label:'体验示例',icon:'layers'},{id:'todo',label:'今日待办',icon:'activity'},{id:'desk',label:'会话工作台',icon:'message'},{id:'tickets',label:'工单跟进',icon:'headset'},{id:'feedback',label:'客户反馈',icon:'layers'},{id:'knowledge',label:'知识与缺口',icon:'book'},{id:'report',label:'服务概况',icon:'activity'},{id:'map',label:'用户任务地图',icon:'layers'},{id:'team',label:'协作空间',icon:'settings'},{id:'monitor',label:'运行监控',icon:'activity'}]
watch(view,value=>window.history.replaceState(null,'','#'+value))
watch(()=>[settings.backend,settings.userId,settings.workspaceId],()=>{readFailure.value=null})
function syncHash(){const target=window.location.hash.slice(1);if(nav.some(n=>n.id===target))navigate(target)}
onMounted(()=>window.addEventListener('hashchange',syncHash))
onUnmounted(()=>window.removeEventListener('hashchange',syncHash))
const title = computed(()=>nav.find(n=>n.id===view.value)?.label)
const pendingCount = computed(()=>conversations.value.filter(c=>c.status!=='resolved').length)
const shownConversations = computed(()=>conversations.value.filter(c=>(queueFilter.value==='all'||queueFilter.value==='unresolved'&&c.status!=='resolved'||c.status===queueFilter.value) && (c.title+' '+c.user_id+' '+(c.order_id||'')).toLowerCase().includes(queueSearch.value.toLowerCase())))
const activeDocs = computed(()=>docs.value.filter(d=>!d.deleted))
const shownDocs = computed(()=>docs.value.filter(d=>includeArchived.value||!d.deleted))
const shownFeedback = computed(()=>feedback.value.filter(r=>(r.content+' '+r.order_id).toLowerCase().includes(feedbackQuery.value.toLowerCase())))
const conversationTickets = computed(()=>tickets.value.filter(t=>t.conv_id===selected.value?.id))
const agents = computed(()=>Object.entries(monitor.value?.agent_stats||{}))
const time = value => value ? new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'}) : '—'
const orderGroups=computed(()=>{const groups=new Map();for(const item of order.value?.items||[]){const g=groups.get(item.product_id)||{product_id:item.product_id,rows:0,price:0,freight:0};g.rows++;g.price+=Number(item.price)||0;g.freight+=Number(item.freight)||0;groups.set(item.product_id,g)}return [...groups.values()]})
const orderStatus = value => ({delivered:'已送达',shipped:'已发货',canceled:'已取消',unavailable:'不可用',processing:'处理中',invoiced:'已开票',created:'已创建',approved:'已确认'}[value]||value)
function inform(text,error=false){ notice.value=text; failed.value=error }
function handleRequestError(e){if(e.transient&&!e.mutation){readFailure.value=e;notice.value='';failed.value=false}else inform(e.message,true)}
function onReadSuccess(event){const e=event.detail;if(e?.type==='success'&&e.method==='GET'&&readFailure.value?.path===e.path&&e.base===backendMeta(settings.backend,settings).baseUrl.replace(/\/+$/,''))readFailure.value=null}
onMounted(()=>window.addEventListener(REQUEST_EVENT,onReadSuccess))
onUnmounted(()=>window.removeEventListener(REQUEST_EVENT,onReadSuccess))
async function guarded(action){if(busy.value)return;busy.value=true;notice.value='';failed.value=false;try{await action()}catch(e){handleRequestError(e)}finally{busy.value=false}}
async function loadLists(){const [c,t]=await Promise.all([api('/conversations?'+userQuery()),api('/tickets?'+userQuery())]);conversations.value=c;tickets.value=t;listsLoaded.value=true;workflowRevision.value++}
async function loadKnowledge(){if(currentSpace.value?.is_demo){demoPolicies.value=await api('/demos/documents?'+userQuery());docs.value=[];imports.value=[];return}demoPolicies.value=[];const [d,i]=await Promise.all([api('/knowledge/documents?include_deleted=true'),api('/knowledge/imports')]);docs.value=d;imports.value=i}
async function loadFeedback(){const data=await api('/feedback');feedback.value=data.reviews;dataset.value=data.source}
let workflowWasAtBottom=true
function beforeWorkflowLoad(){workflowWasAtBottom=!log.value||log.value.scrollHeight-log.value.clientHeight-log.value.scrollTop<45}
async function afterWorkflowLoad(){if(workflowWasAtBottom)await scroll()}
async function scroll(){await nextTick();if(log.value) log.value.scrollTop=log.value.scrollHeight}
let restoring=false
const bufferKey=()=>selected.value?'echomind.editing.'+JSON.stringify([settings.workspaceId||'personal',settings.userId,selected.value.id]):null
function stash(){if(restoring)return;const k=bufferKey();if(k)try{localStorage.setItem(k,JSON.stringify({draft:draft.value,note:noteDraft.value,editingId:editingDraftId.value,content:editedReply.value,revision:messages.value.find(m=>m.id===editingDraftId.value)?.revision||1,manual:manualDraft.value,manualOrigin:manualOrigin.value,operation:operationDraft.value,pending:pendingRequest.value,manualSubmission:manualSubmission.value,mode:composerMode.value}))}catch{inform('浏览器暂不能保存未提交内容，请先保存草稿',true)}}
watch([draft,noteDraft,editingDraftId,editedReply,manualDraft,operationDraft,pendingRequest,manualSubmission,composerMode],stash,{flush:'sync'})
function applyConversation(data){
  stash();restoring=true;selected.value=data;messages.value=data.messages||[];memory.value=data.memory||null
  draft.value='';noteDraft.value='';editingDraftId.value='';editedReply.value='';manualDraft.value='';manualOrigin.value='';operationDraft.value='';pendingRequest.value=null;manualSubmission.value=null;composerMode.value='customer'
  try{const value=JSON.parse(localStorage.getItem(bufferKey())||'null');if(value){draft.value=value.draft||'';noteDraft.value=value.note||'';manualDraft.value=value.manual||'';manualOrigin.value=value.manualOrigin||'';operationDraft.value=value.operation||'';pendingRequest.value=value.pending||null;manualSubmission.value=value.manualSubmission||null;composerMode.value=['customer','note','manual','operation'].includes(value.mode)?value.mode:'customer';const msg=messages.value.find(m=>m.id===value.editingId);if(msg&&msg.review_state!=='adopted'&&(msg.revision||1)===value.revision){editingDraftId.value=value.editingId;editedReply.value=value.content||''}else if(value.content&&value.editingId){noteDraft.value+=(noteDraft.value?'\n':'')+'[恢复的未提交回复，请核对新版本]\n'+value.content;inform('原回复已被更新，已将未提交文字恢复到内部备注输入框，请核对后处理')}}}catch{}
  if(pendingRequest.value){const receipt=(data.reply_requests||[]).find(r=>r.request_id===pendingRequest.value.id);if(receipt?.state==='succeeded'||receipt?.state==='dismissed'){if(pendingRequest.value.kind==='customer_input'&&draft.value.trim()===pendingRequest.value.message)draft.value='';if(pendingRequest.value.kind==='staff_action'&&operationDraft.value.trim()===pendingRequest.value.message)operationDraft.value='';pendingRequest.value=null}else if(receipt){pendingRequest.value={...pendingRequest.value,state:receipt.state,hint:receipt.state==='failed'?'原输入已保存，生成未完成；可重试同次生成或手写回复':'原输入已保存，正在核对生成状态'}}}
  restoring=false;stash();settings.conversationId=data.id;saveSettings(settings)
}
function clearSelection(){pendingTicketCheck.value=null;listsLoaded.value=false;conversations.value=[];tickets.value=[];stash();restoring=true;selected.value=null;messages.value=[];memory.value=null;order.value=null;ticket.value=null;draft.value='';noteDraft.value='';editingDraftId.value='';editedReply.value='';manualDraft.value='';manualOrigin.value='';operationDraft.value='';pendingRequest.value=null;manualSubmission.value=null;composerMode.value='customer';restoring=false;settings.conversationId=''}
async function loadSpaces(){workspaces.value=await api('/workspaces?'+userQuery());if(settings.workspaceId&&!workspaces.value.some(w=>w.id===settings.workspaceId)){settings.workspaceId='';settings.conversationId='';saveSettings(settings)}}
async function openDemoCase({workspaceId,convId,step}){await guarded(async()=>{
  if(!currentSpace.value?.is_demo)settings.demoReturn={userId:settings.userId,workspaceId:settings.workspaceId,conversationId:settings.conversationId}
  clearSelection();await loadSpaces();settings.workspaceId=workspaceId;saveSettings(settings);await Promise.all([loadLists(),loadKnowledge()]);const c=await api('/conversations/'+convId+'?'+userQuery());applyConversation(c);order.value=c.order_id?await api('/orders/'+c.order_id+'?'+userQuery()):null;queueFilter.value='all';queueSearch.value='';view.value='desk';mobileQueue.value=false;await scroll();window.scrollTo(0,0);inform('已打开已有记录，继续提问会追加到这条会话')
});if(step&&selected.value?.id===convId)await goToCaseStep(step)}
async function openHistoricalCase({workspaceId,convId}){await guarded(async()=>{
  if(!currentSpace.value?.is_historical_practice)settings.practiceReturn={userId:settings.userId,workspaceId:settings.workspaceId,conversationId:settings.conversationId}
  clearSelection();await loadSpaces();settings.workspaceId=workspaceId;saveSettings(settings);await Promise.all([loadLists(),loadKnowledge()]);operationsFilter.value='mine'
  if(convId){const c=await api('/conversations/'+convId+'?'+userQuery());applyConversation(c);order.value=c.order_id?await api('/orders/'+c.order_id+'?'+userQuery()):null;queueFilter.value='all';queueSearch.value='';view.value='desk';mobileQueue.value=false;await scroll()}else view.value='todo'
  window.scrollTo(0,0);inform('已打开Olist历史数据练习；原始评价和订单保留，后续处理保存在本机')
})}
async function exitHistoricalPractice(){await guarded(async()=>{const previous=settings.practiceReturn;clearSelection();await loadSpaces();settings.workspaceId=previous?.userId===settings.userId&&workspaces.value.some(w=>w.id===previous.workspaceId)?previous.workspaceId:'';settings.practiceReturn=null;saveSettings(settings);await Promise.all([loadLists(),loadKnowledge()]);const c=conversations.value.find(c=>c.id===previous?.conversationId);if(c){const data=await api('/conversations/'+c.id+'?'+userQuery());applyConversation(data);order.value=data.order_id?await api('/orders/'+data.order_id+'?'+userQuery()):null}view.value='todo';window.scrollTo(0,0);inform('已返回原工作范围，历史练习记录保留')})}
async function exitDemo(){await guarded(async()=>{const previous=settings.demoReturn;clearSelection();await loadSpaces();settings.workspaceId=previous?.userId===settings.userId&&workspaces.value.some(w=>w.id===previous.workspaceId)?previous.workspaceId:'';settings.demoReturn=null;saveSettings(settings);await Promise.all([loadLists(),loadKnowledge()]);const c=conversations.value.find(c=>c.id===previous?.conversationId);if(c){const data=await api('/conversations/'+c.id+'?'+userQuery());applyConversation(data);order.value=data.order_id?await api('/orders/'+data.order_id+'?'+userQuery()):null}view.value='desk';await scroll();window.scrollTo(0,0);inform('已返回工作范围；演示记录保留，可从体验示例继续')})}
async function fillDemoPrompt(text){if(busy.value||pendingRequest.value){inform('请先完成或停止当前生成，再填写新的追问');return}if(draft.value.trim()&&draft.value.trim()!==text){inform('输入框已有未提交内容，请先保留或清空，再选择追问');return}composerMode.value='customer';draft.value=text;await nextTick();window.document.getElementById('reply')?.focus()}
async function changeWorkspace(id){await guarded(async()=>{clearSelection();await loadSpaces();settings.workspaceId=id||'';saveSettings(settings);await Promise.all([loadLists(),loadKnowledge()]);inform('已切换到'+(currentSpace.value?.name||'个人记录'))})}
async function selectConversation(id){
  if(busy.value)return
  await guarded(async()=>{const data=await api('/conversations/'+id+'?'+userQuery());applyConversation(data);view.value='desk';mobileQueue.value=false;order.value=data.order_id?await api('/orders/'+data.order_id+'?'+userQuery()):null;await scroll();window.scrollTo(0,0)})
}
async function createConversation(){await guarded(async()=>{const c=await api('/conversations','POST',{user_id:settings.userId,title:'新服务事项',knowledge_mode:'business'});await loadLists();applyConversation(c);order.value=null;view.value='desk';mobileQueue.value=false})}
function finishReply(request,fresh){
  if(request.kind==='customer_input'&&draft.value.trim()===request.message)draft.value=''
  if(request.kind==='staff_action'&&operationDraft.value.trim()===request.message)operationDraft.value=''
  pendingRequest.value=null;applyConversation(fresh)
}
async function performReply(request){
  if(busy.value||!selected.value)return
  await guarded(async()=>{
    pendingRequest.value={...request,state:'running',hint:'输入保留中，正在生成回复'}
    try{
      await requestChat(settings.backend,{...settings,conversationId:selected.value.id,replyRequestId:request.id,inputKind:request.kind,replyAction:request.action},request.message)
      const fresh=await api('/conversations/'+selected.value.id+'?'+userQuery());finishReply(request,fresh);inform(request.kind==='staff_action'?'客服操作完成；操作记录与客户原话分开保存':'原话与回复草稿已保存')
    }catch(error){
      let fresh=null
      try{fresh=await api('/conversations/'+selected.value.id+'?'+userQuery())}catch{}
      const receipt=fresh?.reply_requests?.find(r=>r.request_id===request.id)
      if(receipt?.state==='succeeded'){finishReply(request,fresh);inform('生成已完成，已恢复服务端结果')}
      else{pendingRequest.value={...request,state:receipt?.state||'unknown',hint:receipt?'原输入已保存，生成未完成；可重试同次生成或手写回复':'输入已保留；暂未确认服务端状态，恢复连接后可重试'};if(fresh)applyConversation(fresh);inform(pendingRequest.value.hint,true)}
    }
    try{await loadLists()}catch{}
    await scroll()
  })
}
async function stopRetry(){if(!pendingRequest.value)return;await guarded(async()=>{const request=pendingRequest.value;await api('/conversations/'+selected.value.id+'/requests/'+encodeURIComponent(request.id)+'/dismiss','POST',{user_id:settings.userId});if(request.kind==='customer_input'&&draft.value.trim()===request.message)draft.value='';if(request.kind==='staff_action'&&operationDraft.value.trim()===request.message)operationDraft.value='';pendingRequest.value=null;await reloadConversation();inform('已停止重试，原输入与失败记录保留；可继续手写回复')})}
async function saveManual(){
  const text=manualDraft.value.trim();if(!text||!selected.value||busy.value)return
  await guarded(async()=>{if(!manualSubmission.value||manualSubmission.value.content!==text||(manualSubmission.value.source_reference_id||'')!==manualOrigin.value)manualSubmission.value={id:crypto.randomUUID(),content:text,source_reference_id:manualOrigin.value};const saved=await api('/conversations/'+selected.value.id+'/drafts/manual','POST',{user_id:settings.userId,content:text,request_id:manualSubmission.value.id,...(manualOrigin.value?{source_reference_id:manualOrigin.value}:{})});manualDraft.value='';manualOrigin.value='';manualSubmission.value=null;await reloadConversation();beginDraft(saved);await loadLists();inform('人工草稿已保存，可继续核对、采用、复制或导出；未调用模型');await scroll()})
}
async function send(){
  if(composerMode.value==='note'){await addNote();return}
  if(composerMode.value==='manual'){await saveManual();return}
  if(pendingRequest.value){await performReply(pendingRequest.value);return}
  const text=(composerMode.value==='operation'?operationDraft.value:draft.value).trim();if(!text||!selected.value||busy.value)return
  await performReply({id:crypto.randomUUID(),message:text,kind:composerMode.value==='operation'?'staff_action':'customer_input',action:composerMode.value==='operation'?'custom':null})
}
async function staffAction(action){
  if(pendingRequest.value){inform('请先恢复上次生成状态；也可以切换到手写回复继续处理',true);return}
  const prompts={translate:'把客户原文翻译成中文并概括客户诉求',order_facts:'只根据关联订单核对订单状态和比预计晚到几天，不推断赔付规则',redraft:'根据最近一条客户原话重新准备回复'}
  await performReply({id:crypto.randomUUID(),message:prompts[action],kind:'staff_action',action})
}

function key(event){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();send()}}
async function patchConversation(patch){if(!selected.value)return;await guarded(async()=>{selected.value=await api('/conversations/'+selected.value.id,'PATCH',{user_id:settings.userId,...patch});await loadLists();inform(patch.knowledge_mode?'已切换知识模式；采用回复前会重新检查依据':'会话已更新')})}
async function createTicket(){await guarded(async()=>{const t=await api('/tickets','POST',{user_id:settings.userId,conv_id:selected.value.id});await loadLists();openTicket(t);inform(t.status==='resolved'?'已打开原已解决工单；继续处理请填写原因重新打开':'已打开本地工单，请安排负责人和下一步')})}
function localDate(value){if(!value)return '';return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)).replace(' ','T')}
const uncertainTicketKey=id=>formDraftKey(settings,'ticket-save-unknown',id)
function openTicket(t){if(!t){inform('工单记录未找到，请刷新工单列表',true);return}stash();pendingTicketCheck.value=readFormDraft(uncertainTicketKey(t.id));ticketHydrating=true;ticket.value=t;ticketFormKey=formDraftKey(settings,'ticket',t.id);Object.assign(ticketEdit,{owner:t.owner,status:t.status,note:'',priority:t.priority||'normal',due_at:localDate(t.due_at),wait_reason:t.wait_reason||'',next_action:t.next_action||'',resolution:t.resolution||'',closure_exception:'',closure_plan:null,handoff_plan:{context_hash:'',decisions:[]}});ticketInitial=copyForm(ticketEdit);ticketBaseRevision.value=t.revision||1;const saved=readFormDraft(ticketFormKey);if(saved){Object.assign(ticketEdit,saved.fields);ticketBaseRevision.value=saved.base}ticketDraftConflict.value=!!saved&&saved.base!==(t.revision||1);ticketHydrating=false;handoffNote.value='';view.value='tickets'}
async function saveTicket(){if(pendingTicketCheck.value)return;await guarded(async()=>{
  const id=ticket.value.id,base=ticketBaseRevision.value,key=ticketFormKey,uncertainKey=uncertainTicketKey(id)
  let saved
  try{saved=await api('/tickets/'+id,'PATCH',{user_id:settings.userId,...ticketEdit,closure_plan:ticketEdit.status==='resolved'?ticketEdit.closure_plan:null,handoff_tasks:ticketEdit.handoff_plan?.decisions||[],handoff_context_hash:ticketEdit.handoff_plan?.context_hash||null,due_at:ticketEdit.due_at?new Date(ticketEdit.due_at+':00+08:00').toISOString():null,expected_revision:base})}
  catch(e){if(e.transient){pendingTicketCheck.value={id,base};writeFormDraft(uncertainKey,pendingTicketCheck.value);inform('暂未确认这次工单是否保存成功。填写内容已保留，请先核对当前记录。',true);return}throw e}
  clearFormDraft(key);clearFormDraft(uncertainKey);openTicket(saved)
  try{await loadLists();if(selected.value?.id===saved.conv_id)await reloadConversation()}catch(e){if(e.transient&&!e.mutation){readFailure.value=e;inform('工单已保存；列表暂时未能刷新，可在连接恢复后重新读取。');return}throw e}
  inform(saved.handoff?.state==='pending'?'交接已发起；'+saved.owner+' 继续负责，等待 '+saved.handoff.candidate+' 接受':'跟进安排已保存；到期会显示在本地待办中')
})}
async function checkTicketSave(){const pending=pendingTicketCheck.value;if(!pending)return;await guarded(async()=>{const current=await api('/tickets?'+userQuery());const found=current.find(t=>t.id===pending.id);if(!found)throw Error('当前范围未找到此工单，请先核对工作范围。');tickets.value=current;clearFormDraft(uncertainTicketKey(pending.id));pendingTicketCheck.value=null;openTicket(found);inform(found.revision!==pending.base?'当前工单已有更新，请核对处理历史；未提交文字已保留，确认后再继续。':'已读取当前版本，尚未看到版本更新。请核对保留的内容后再决定是否保存。')})}

async function decideHandoff(action){await guarded(async()=>{const saved=await api('/tickets/'+ticket.value.id+'/handoff','POST',{user_id:settings.userId,action,note:handoffNote.value.trim()||(action==='accept'?'已核对交接内容，接受处理':''),expected_revision:ticket.value.revision||1});openTicket(saved);await loadLists();if(selected.value?.id===saved.conv_id)await reloadConversation();inform(action==='accept'?'已接受交接，当前由你负责':'已退回交接，原责任人继续跟进')})}
async function reopenTicket(){await guarded(async()=>{const saved=await api('/tickets/'+ticket.value.id+'/reopen','POST',{user_id:settings.userId,note:ticketEdit.note});clearFormDraft(ticketFormKey);await loadLists();openTicket(saved);if(selected.value?.id===saved.conv_id)await reloadConversation();inform('原工单已重新打开，结案历史保留')})}
async function goToCaseStep(step){if(step.kind==='exception'){await nextTick();window.document.getElementById(closureDialog.value?.open?'case-closure-exception':'ticket-closure-exception')?.focus();return}closureDialog.value?.close();if(step.kind==='ticket'){let t=tickets.value.find(t=>t.id===step.id);if(!t){await loadLists();t=tickets.value.find(t=>t.id===step.id)}openTicket(t);return}if(selected.value?.id!==step.conv_id||view.value!=='desk')await selectConversation(step.conv_id);await nextTick();await followupPanel.value?.openSection(step.kind,step.id)}
let restoringClosure=false
watch([closureReason,closureException,closurePlan],()=>{if(restoringClosure||!selected.value)return;writeFormDraft(formDraftKey(settings,'closure',selected.value.id),{reason:closureReason.value,exception:closureException.value,plan:closurePlan.value})},{deep:true,flush:'sync'})
function statusChange(event){const value=event.target.value;event.target.value=selected.value.status;if(value==='resolved'){restoringClosure=true;const saved=readFormDraft(formDraftKey(settings,'closure',selected.value.id));closureReason.value=saved?.reason||'';closureException.value=saved?.exception||'';closurePlan.value=saved?.plan||{};restoringClosure=false;workflowRevision.value++;closureDialog.value.showModal()}else patchConversation({status:value})}
async function closeCase(){await patchConversation({status:'resolved',resolution:closureReason.value,closure_exception:closureException.value,closure_plan:closurePlan.value.kind?closurePlan.value:null});if(!failed.value){clearFormDraft(formDraftKey(settings,'closure',selected.value.id));closureDialog.value.close()}else{closureErrorCaseId.value=selected.value.id;workflowRevision.value++;await nextTick();window.document.getElementById('case-close-error')?.focus()}}
watch(intake,()=>{if(intakeHydrating||!intakeDraftKey)return;intakeDraftNotice.value=writeFormDraft(intakeDraftKey,copyForm(intake))?'未提交内容已保留；关闭或刷新后可继续。':'浏览器无法保存未提交内容，请先保存受理信息再离开。'},{deep:true,flush:'sync'})
function showIntake(){intakeHydrating=true;intakeDraftKey=formDraftKey(settings,'intake',selected.value.id);const saved=readFormDraft(intakeDraftKey);Object.assign(intake,{issue_type:'other',product_id:'',quantity:null,desired_outcome:'',evidence_note:''},selected.value?.intake||{},saved||{});intakeDraftNotice.value=saved?'已恢复本事项未提交的受理信息。':'关闭后会保留未提交内容。';intakeHydrating=false;intakeDialog.value.showModal()}
async function saveIntake(){const key=intakeDraftKey;await patchConversation({intake:{...intake,quantity:intake.quantity?Number(intake.quantity):null}});if(!failed.value){clearFormDraft(key);intakeDialog.value.close()}}
async function onFollowupChanged(){if(closureErrorCaseId.value===selected.value?.id){closureErrorCaseId.value='';inform('材料或客户记录已更新，请重新核对结案条件。')}await loadLists()}
async function createGap(){if(!selected.value)return;await guarded(async()=>{const question=[...messages.value].reverse().find(m=>m.role==='user')?.content||selected.value.title;await api('/knowledge/gaps','POST',{user_id:settings.userId,conv_id:selected.value.id,question});await loadKnowledge();view.value='knowledge';inform('知识缺口已登记并关联原事项，请分派维护人')})}
async function translateReply(m){await guarded(async()=>{const language=translationLanguages[m.id]||'pt-BR';const key=formDraftKey(settings,'translation',selected.value.id+':'+m.id);let req=readFormDraft(key);if(!req||req.language!==language||req.revision!==m.revision){req={language,revision:m.revision,id:crypto.randomUUID()};writeFormDraft(key,req)}await api('/conversations/'+selected.value.id+'/drafts/'+m.id+'/translate','POST',{user_id:settings.userId,target_language:language,expected_revision:m.revision||1,request_id:req.id});clearFormDraft(key);await reloadConversation();inform('译稿已另存，请核对含义与适用政策后采用；原稿保留');await scroll()})}
async function reviseReply(m){await guarded(async()=>{const revision=await api('/conversations/'+selected.value.id+'/drafts/'+m.id+'/revise','POST',{user_id:settings.userId});await reloadConversation();beginDraft(revision);inform('已创建独立修订草稿，原采用版本保留');await scroll()})}
function isReference(m){return m.output_type==='reference'||m.kind==='assistant_reference'||m.knowledge_status==='source_translation'}
async function prepareReference(m){const text=m.suggested_reply||'';if(manualDraft.value.trim()&&manualDraft.value!==text){inform('手写回复中已有未提交内容，请先保留或清空后再准备新的草稿');return}manualDraft.value=text;manualOrigin.value=m.id;composerMode.value='manual';await nextTick();window.document.getElementById('manual-reply')?.focus();inform('已单独准备客户回复草稿，请核对正文后保存；客服参考保持原记录')}
async function copyReply(m){try{await navigator.clipboard.writeText(editingDraftId.value===m.id?editedReply.value:m.content);inform(isReference(m)?'已复制客服参考，请勿作为客户回复直接发送':'已复制回复正文，仍需在业务渠道发送')}catch{inform('浏览器未允许复制，可使用“导出正文”保存',true)}}
function exportReply(m){const content=editingDraftId.value===m.id?editedReply.value:m.content;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=window.document.createElement('a');a.href=url;a.download=(isReference(m)?'客服参考-':'回复-')+m.id.slice(0,8)+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);inform(isReference(m)?'已导出客服参考':'已导出回复正文，未向客户发送')}
async function openDemoPolicy(id){await guarded(async()=>{demoPolicy.value=await api('/demos/documents/'+id+'?'+userQuery());await nextTick();demoPolicyDialog.value.showModal()})}
async function openDoc(id,version,kind){if(kind==='demo_policy')return openDemoPolicy(id);await guarded(async()=>{await loadKnowledge();const d=await api('/knowledge/documents/'+id+(version?'?version='+version:''));document.value=d;Object.assign(editor,{title:d.title,content:d.content,version:d.version,scope:d.scope||'test'});reviewNote.value='';view.value='knowledge'})}
async function changeVersion(e){await openDoc(document.value.document_id||document.value.id,Number(e.target.value))}
async function saveDoc(){await guarded(async()=>{const id=document.value.document_id||document.value.id;await api('/knowledge/documents/'+id,'PUT',editor);document.value=await api('/knowledge/documents/'+id);Object.assign(editor,{title:document.value.title,content:document.value.content,version:document.value.version,scope:document.value.scope||'test'});await loadKnowledge();results.value=[];searched.value=false;inform('已保存为新草稿；业务模式继续使用上一生效版，审核通过后切换')})}
async function archiveDoc(){await guarded(async()=>{const id=document.value.document_id||document.value.id;await api('/knowledge/documents/'+id,'DELETE');document.value=await api('/knowledge/documents/'+id);await loadKnowledge();results.value=[];searched.value=false;inform('文档已移入归档，停止参与检索；可随时恢复')})}
async function restoreDoc(){await guarded(async()=>{const id=document.value.document_id||document.value.id;await api('/knowledge/documents/'+id+'/restore','POST');document.value=await api('/knowledge/documents/'+id);Object.assign(editor,{title:document.value.title,content:document.value.content,version:document.value.version,scope:document.value.scope||'test'});await loadKnowledge();inform('已恢复为新草稿；业务知识需重新审核后生效')})}
async function addDoc(){await guarded(async()=>{await api('/knowledge/add','POST',{documents:[{...newDoc}]});await loadKnowledge();docDialog.value.close();newDoc.title='';newDoc.content='';inform('已导入为草稿；业务知识需审核后生效，测试资料仅用于测试')})}
async function upload(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await guarded(async()=>{inform('正在解析并建立索引：'+file.name);await uploadKnowledge(settings.backend,settings,file,importScope.value);await loadKnowledge();inform('已导入为草稿：'+file.name+'；业务知识需审核后生效')})}
async function search(){await guarded(async()=>{const data=await api('/search?'+new URLSearchParams({query:query.value,top_k:'5',mode:searchMode.value}),'POST');results.value=data.results||[];searched.value=true;inform(data.status==='unavailable'?'检索服务暂时不可用，请稍后重试':'检索完成；请核对原文')})}
async function searchOrders(){await guarded(async()=>{orderResults.value=await api('/orders?'+userQuery()+'&query='+encodeURIComponent(orderQuery.value))})}
async function linkOrder(o){await guarded(async()=>{selected.value=await api('/conversations/'+selected.value.id,'PATCH',{user_id:settings.userId,order_id:o.id});order.value=o;orderResults.value=[];await loadLists();inform('已关联本地只读历史订单')})}
async function feedbackCase(r){await guarded(async()=>{const data=await api('/feedback/'+encodeURIComponent(r.id)+'/case','POST',{user_id:settings.userId});await loadLists();const c=await api('/conversations/'+data.conversation.id+'?'+userQuery());applyConversation(c);order.value=await api('/orders/'+c.order_id+'?'+userQuery());view.value='desk';inform(data.already_exists?'已打开此工作范围内的原事项，未重复创建':'真实评价已受理，原文和订单已关联；未执行退款');await scroll()})}
async function navigate(next){if(busy.value)return;stash();const target=typeof next==='string'?next:next.view;operationsFilter.value=(typeof next==='object'?next.filter:null)||(target==='todo'?'mine':'all');if(target==='desk')queueFilter.value=next.filter||'all';view.value=target;notice.value='';await nextTick();window.scrollTo(0,0);await guarded(async()=>{if(target==='knowledge')await loadKnowledge();if(target==='tickets'||target==='desk'||target==='feedback')await loadLists();if(target==='feedback')await loadFeedback();if(target==='team')await loadSpaces();if(target==='monitor')monitor.value=await api('/monitor')})}
async function applyIdentity(){const id=identity.value.trim();if(!id)return;await guarded(async()=>{clearSelection();settings.userId=id;await loadSpaces();saveSettings(settings);await loadLists();identityDialog.value.close();inform('已切换本地成员；请选择工作范围，再打开原事项')})}
async function reloadConversation(){const c=await api('/conversations/'+selected.value.id+'?'+userQuery());applyConversation(c)}
async function addNote(){if(!noteDraft.value.trim()||!selected.value)return;await guarded(async()=>{await api('/conversations/'+selected.value.id+'/notes','POST',{user_id:settings.userId,content:noteDraft.value});noteDraft.value='';await reloadConversation();await loadLists();inform('内部备注已保存；不进入模型上下文，也未发送给客户');await scroll()})}
function beginDraft(m){editingDraftId.value=m.id;editedReply.value=m.content}
async function saveReply(m,adopt=false){await guarded(async()=>{await api('/conversations/'+selected.value.id+'/drafts/'+m.id,'PATCH',{user_id:settings.userId,content:editingDraftId.value===m.id?editedReply.value:m.content,revision:m.revision||1,adopt});editingDraftId.value='';editedReply.value='';await reloadConversation();await loadLists();inform(adopt?'回复已采用并保存在本机；未向客户发送':'修改已保存，原始生成内容与修改历史保留')})}
async function reviewDoc(action){await guarded(async()=>{const id=document.value.document_id||document.value.id;await api('/knowledge/documents/'+id+'/review','POST',{actor:settings.userId,action,version:document.value.version,note:reviewNote.value});document.value=await api('/knowledge/documents/'+id);Object.assign(editor,{title:document.value.title,content:document.value.content,version:document.value.version,scope:document.value.scope});reviewNote.value='';await loadKnowledge();results.value=[];searched.value=false;inform(action==='approve'?(document.value.scope==='business'?'此版本已在业务知识模式生效':'测试资料已审核，仍仅用于测试模式'):action==='submit'?'已提交本地审核':'已退回草稿，审核说明已保留')})}
function jumpMessage(id){view.value='desk';nextTick(()=>window.document.getElementById('message-'+id)?.scrollIntoView({block:'center',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}))}
async function initializeData(){await loadSpaces();await Promise.all([loadLists(),loadKnowledge(),loadFeedback()]);if(!selected.value){const c=conversations.value.find(c=>c.id===settings.conversationId)||conversations.value[0];if(c){const data=await api('/conversations/'+c.id+'?'+userQuery());applyConversation(data);order.value=c.order_id?await api('/orders/'+c.order_id+'?'+userQuery()):null;await scroll()}else{settings.conversationId='';saveSettings(settings)}}initialized=true}
async function refreshReadOnly(options={}){const keepNotice=options.automatic&&failed.value?notice.value:'';await guarded(async()=>{if(!initialized)await initializeData();else{await Promise.all([loadLists(),loadKnowledge(),loadFeedback()]);if(view.value==='monitor')monitor.value=await api('/monitor')}readFailure.value=null});if(keepNotice)inform(keepNotice,true)}
onMounted(async()=>{await guarded(initializeData)})
</script>

<template>
<a class="skip-link" href="#main-content">跳到工作内容</a>
<div class="shell">
  <aside class="rail">
    <a class="brand" href="#" aria-label="知应 · 客户服务与工单协作台" @click.prevent="navigate('desk')"><span class="brand-icon"><UiIcon name="headset" :size="23"/></span><span>知应<small>客户服务与<br/>工单协作台</small></span></a>
    <button class="primary new-session" :disabled="busy" @click="createConversation"><UiIcon name="plus" :size="17"/>录入客户问题</button>
    <nav aria-label="工作台导航"><button v-for="n in nav" :key="n.id" :class="{active:view===n.id}" :aria-label="n.label" :aria-current="view===n.id?'page':undefined" :disabled="busy" @click="navigate(n.id)"><UiIcon :name="n.icon" :size="19"/><span>{{n.label}}</span><b v-if="n.id==='tickets'&&listsLoaded">{{tickets.filter(t=>t.status!=='resolved').length}}</b></button></nav>
    <div class="rail-bottom"><div class="local-label"><i/>本地演示环境</div><p>历史订单只读<br>工单保存在本机</p><button class="identity" :disabled="busy" @click="identity=settings.userId;identityDialog.showModal()"><span class="avatar">客</span><span>{{settings.userId}}<small>切换工作台用户</small></span><UiIcon name="settings" :size="16"/></button></div>
  </aside>
  <main id="main-content" class="main" :aria-busy="busy">
    <header class="topbar"><div><span>服务运营</span><UiIcon name="chevron" :size="13"/><strong>{{title}}</strong></div><label class="workspace-picker">工作范围<select :value="settings.workspaceId" aria-label="工作范围" :disabled="busy" @change="changeWorkspace($event.target.value)"><option value="">个人记录</option><option v-for="w in workspaces" :key="w.id" :value="w.id">{{w.name}}</option></select></label><span class="health"><i :class="{online}"/>{{online?'本机服务已连接':connection.state.value==='checking'?'正在检查连接':'正在重新连接'}}</span></header>
    <ConnectionNotice :state="connection.state.value" :checking="connection.checking.value" :recovered="connection.recovered.value" :read-error="readFailure" :busy="busy" @check="connection.check" @reload="refreshReadOnly"/>
    <div v-if="notice" class="notice" :class="{error:failed}" :role="failed?'alert':'status'">{{notice}}<button aria-label="关闭提示" @click="notice=''">×</button></div>
    <div v-if="busy" class="progress" role="status">正在处理，请稍候…</div>

    <div v-if="currentSpace?.is_demo && view!=='examples' && view!=='desk'" class="demo-scope demo-global"><span>演示练习空间 · 当前记录为合成案例与练习数据</span><button class="text-button" :disabled="busy" @click="exitDemo">退出演示</button></div>
    <div v-if="currentSpace?.is_historical_practice" class="history-global"><span>Olist 历史数据练习 · 2016—2018 年评价与只读订单 · 当前操作为本地练习</span><button type="button" class="text-button" :disabled="busy" @click="exitHistoricalPractice">返回原工作范围</button></div>
    <DemoHub v-if="view==='examples'" :settings="settings" :disabled="busy" @open="openDemoCase" @exit="exitDemo"/>
    <section v-else-if="view==='desk'" class="desk">
      <aside class="queue" :class="{mobileOpen:mobileQueue}"><header><div><h1>服务队列</h1><span>{{pendingCount}} 个待处理会话</span></div><button class="icon" aria-label="新建会话" :disabled="busy" @click="createConversation"><UiIcon name="plus" :size="20"/></button></header>
        <button class="demo-quick-entry" :disabled="busy" @click="navigate('examples')">从完整案例开始 → 体验示例</button>
        <label class="searchbox"><UiIcon name="search" :size="16"/><input v-model="queueSearch" aria-label="筛选服务队列" placeholder="搜索会话、订单…"/></label>
        <div class="queue-tabs"><button :class="{selected:queueFilter==='all'}" @click="queueFilter='all'">全部 {{conversations.length}}</button><button :class="{selected:queueFilter==='pending'}" @click="queueFilter='pending'">待跟进</button><button :class="{selected:queueFilter==='resolved'}" @click="queueFilter='resolved'">已解决</button></div>
        <div class="queue-list"><button v-for="c in shownConversations" :key="c.id" class="case-row" :class="{selected:selected?.id===c.id}" :disabled="busy" @click="selectConversation(c.id)"><div class="row-meta"><span class="badge" :class="c.status">{{labels[c.status]}}</span><time>{{time(c.updated_at)}}</time></div><h2>{{c.title}}</h2><p>{{previewText(c.preview)||'尚无消息，等待输入'}}</p><div class="case-foot"><span>{{c.source==='Olist真实历史评价'?'Olist 历史反馈':c.source?.startsWith('迁移')?'迁移历史':(c.knowledge_mode==='business'?'客户问题录入':'机器人对话测试')}}</span><span>{{c.owner}}</span></div></button><div v-if="!shownConversations.length" class="small-empty">{{listsLoaded?'暂无会话。录入客户问题，或从客户反馈创建处理事项。':'会话尚未读取，请等待连接恢复后再查看。'}}</div></div>
        <footer>{{currentSpace?.name||settings.userId+' 的个人记录'}} · 自动保存</footer>
      </aside>
      <div class="conversation">
        <header class="conversation-head"><button class="mobile-queue" @click="mobileQueue=!mobileQueue">服务队列</button><div><h2>{{selected?.title||'请选择服务事项'}}</h2><p>{{selected?.source||'从左侧队列继续处理，或录入客户问题'}}</p></div><select v-if="selected" class="knowledge-mode" :value="selected.knowledge_mode||'test'" aria-label="会话知识模式" :disabled="busy||selected.is_demo" @change="patchConversation({knowledge_mode:$event.target.value})"><option value="test">{{selected.is_demo?'隔离演示规则':'草稿 / 示例测试'}}</option><option value="business">已生效业务知识</option></select><select v-if="selected" :value="selected.status" aria-label="会话状态" :disabled="busy" @change="statusChange"><option value="open">待处理</option><option value="pending">待跟进</option><option value="resolved">已解决</option></select></header>
        <aside v-if="selected?.is_historical_practice" class="historical-case-context"><strong>人工中文导读 · 需结合下方葡萄牙语原文核对</strong><p>{{selected.practice_guide}}</p><small>评价描述的是历史当时的情况，订单展示历史最终状态；两者可能不同。</small></aside>
        <DemoGuide v-if="selected?.is_demo" :conversation="selected" :settings="settings" :disabled="busy" @prompt="fillDemoPrompt" @examples="navigate('examples')" @exit="exitDemo" @policy="openDemoPolicy"/>
        <CaseProgress v-if="selected" @loading="beforeWorkflowLoad" @ready="afterWorkflowLoad" :conversation-id="selected.id" :settings="settings" :refresh-token="workflowRevision" @action="goToCaseStep"/>
        <div ref="log" class="message-log" role="log" aria-label="完整会话记录" aria-live="polite">
          <div class="session-note" v-if="selected"><UiIcon name="shield" :size="16"/><span>{{selected.is_demo?'演示模式：仅使用此案例的合成规则。':(selected.knowledge_mode||'test')==='business'?'业务模式：仅使用本机审核后生效的业务知识。':'测试模式：可检索示例和未生效草稿。'}} 采用回复仅作本地记录，未向客户发送。</span></div>
          <div v-if="!messages.length" class="conversation-empty"><UiIcon name="message" :size="28"/><h3>{{selected?'记录客户问题，核对回复依据':'没有选中的会话'}}</h3><p>{{selected?'录入客户原话并核对事实与政策。每条消息及检索依据都会保存在当前会话。':'从服务队列选择事项，或录入一条新的客户问题。'}}</p><button v-if="!selected" class="secondary" :disabled="busy" @click="createConversation">录入客户问题</button></div>
          <article v-for="m in messages" :key="m.id" :id="'message-'+m.id" class="message" :class="m.role"><div class="message-heading"><span class="message-avatar"><UiIcon :name="m.role==='assistant'?'headset':m.role==='system'?'activity':'message'" :size="16"/></span><strong>{{m.role==='assistant'?(m.legacy?'历史回复（来源未记录）':isReference(m)?'客服参考 · 仅供内部核对':m.review_state==='adopted'?'已采用回复（未发送）':m.manual?'人工回复草稿 · 待核对':'回复草稿 · 待核对'):m.role==='note'?'内部备注':m.role==='operation'?'客服操作 · '+(m.author||''):m.role==='system'?'处理记录':m.source==='真实葡萄牙语评价原文'?'客户评价原文':(selected?.knowledge_mode||'test')==='test'?'模拟客户问题':'录入的客户原话'}}</strong><time>{{time(m.created_at)}}</time><span v-if="m.latency_ms" class="latency">{{(m.latency_ms/1000).toFixed(1)}}s</span></div><div class="message-body"><small v-if="m.source_created_at" class="source-note original-time">评价记录创建：{{m.source_review_created_at||m.source_created_at}}<br/>客户评价作答：{{m.source_answered_at||'源数据未收录'}} · 原始时间，未转换时区；消息右上角为本地受理时间。</small><small v-if="m.demo_seed" class="demo-seed-label">预置演示记录 · 合成案例内容</small><MarkdownContent :markdown="m.content"/><ReviewTranslation v-if="m.source==='真实葡萄牙语评价原文'&&selected?.review_id" :review-id="selected.review_id" :source-text="m.content" :settings="settings"/><small v-if="m.role==='operation'" class="operation-privacy">客服操作记录 · 不计入客户原话或客户要点</small><small v-if="m.manual" class="source-note manual-origin">人工撰写，请核对事实与适用政策</small><small v-if="m.role==='note'" class="note-privacy">仅工作台可见 · 不进入客户回复或模型上下文</small><ReplyProcessing v-if="m.role==='assistant'&&!m.legacy" :message="m"/><div v-if="m.role==='assistant'" class="evidence"><span v-if="m.legacy" class="no-match">旧版记录未保存来源引用，请重新提问核对当前知识。</span><span v-if="m.knowledge_status==='no_match'||m.knowledge_status==='unavailable'" class="no-match">{{m.knowledge_status==='unavailable'?'知识检索暂不可用':'当前模式未命中可核对知识'}}</span><div v-if="m.sources?.length"><small>检索依据 · 点击核对版本原文</small><a v-for="s in m.sources" :key="s.document_id+':'+s.chunk" :href="backendMeta(settings.backend,settings).baseUrl+(s.kind==='demo_policy'?'/demos/documents/'+s.document_id+'?'+userQuery()+'&workspace_id='+encodeURIComponent(settings.workspaceId):s.url)" @click.prevent="openDoc(s.document_id,s.version,s.kind)"><UiIcon name="file" :size="14"/>[{{s.citation}}] {{s.title}}<span>v{{s.version}} · {{s.kind==='demo_policy'?'仅此案例演示':s.scope==='business'&&s.review_status==='approved'?'业务生效':'测试 / 草稿'}} · 片段 {{s.chunk+1}}</span></a></div><button v-for="source in m.record_sources||[]" :key="source.kind+source.id" class="text-button record-source-link" @click="goToCaseStep(source)">{{source.label}}</button><button v-for="id in m.context_reference_ids||[]" :key="id" class="text-button" @click="jumpMessage(id)">核对客户原话</button><button v-if="m.ticket_id" class="text-button" @click="openTicket(tickets.find(t=>t.id===m.ticket_id))">查看本地工单 {{m.ticket_id}}</button></div><div v-if="m.data_sources?.length" class="data-sources"><button v-for="source in m.data_sources" :key="source.id" class="text-button" @click="orderQuery=source.id;searchOrders()">事实依据：{{source.label}} · {{source.id}}</button></div><div v-if="m.role==='assistant'&&isReference(m)" class="staff-reference-actions"><p>这是客服参考，不作为客户回复采用。准备回复时会另建草稿。</p><p v-if="m.review_state==='adopted'">此历史记录曾被采用，原采用记录保留；现在按客服参考只读展示。</p><details v-if="m.suggested_reply"><summary>查看可准备的客户回复</summary><p>{{m.suggested_reply}}</p></details><div class="actions"><button type="button" class="primary" :disabled="busy" @click="prepareReference(m)">{{m.suggested_reply?'准备客户回复草稿':'撰写客户回复'}}</button><button type="button" class="secondary" @click="copyReply(m)">复制客服参考</button><button type="button" class="secondary" @click="exportReply(m)">导出客服参考</button></div></div><div v-if="m.role==='assistant'&&!m.legacy&&!isReference(m)" class="reply-review"><template v-if="m.review_state!=='adopted'"><form v-if="editingDraftId===m.id" class="draft-editor" @submit.prevent="saveReply(m)"><label :for="'draft-edit-'+m.id">编辑回复草稿</label><textarea :id="'draft-edit-'+m.id" v-model="editedReply" rows="6" required maxlength="16000"/><p class="source-note">手工修改保留原生成记录；原检索片段仅供核对，不自动证明修改内容正确。</p><div class="actions"><button class="secondary" :disabled="busy||!editedReply.trim()">保存修改</button><button class="primary" type="button" :disabled="busy||!editedReply.trim()" @click="saveReply(m,true)">保存并采用（未发送）</button><button type="button" class="text-button" :disabled="busy" @click="editingDraftId=''">取消</button></div></form><div v-else class="actions"><button class="secondary" :disabled="busy" @click="beginDraft(m)">修改草稿</button><button class="primary" :disabled="busy" @click="saveReply(m,true)">采用回复（仅本地）</button><span class="draft-state">未采用 · 版本 {{m.revision||1}}</span></div></template><p v-else class="adopted-state">{{m.adopted_by}} 已采用 · {{time(m.adopted_at)}} · 未发送给客户</p><button v-if="m.source_reference_id" type="button" class="text-button" @click="jumpMessage(m.source_reference_id)">核对草稿所依据的客服参考</button><details v-if="m.translation_source_id"><summary>核对翻译原稿 · {{m.target_language}} · 原稿版本 {{m.translation_source_revision}}</summary><p class="source-note">译稿不自动证明政策正确；原稿变更后需要重新翻译。</p><MarkdownContent :markdown="m.translation_source_content||''"/><button type="button" class="text-button" @click="jumpMessage(m.translation_source_id)">查看当前原稿</button></details><div class="actions reply-output"><label>翻译目标语言<select :aria-label="'翻译目标语言 '+m.id" v-model="translationLanguages[m.id]"><option :value="undefined">巴西葡萄牙语</option><option value="en">英语</option><option value="zh-CN">简体中文</option><option value="es">西班牙语</option></select></label><button type="button" class="secondary" :disabled="busy||(editingDraftId===m.id&&editedReply!==m.content)" @click="translateReply(m)">翻译这份回复</button><button class="secondary" :disabled="busy" @click="copyReply(m)">复制正文</button><button class="secondary" @click="exportReply(m)">导出正文</button><button v-if="m.review_state==='adopted'" class="secondary" :disabled="busy" @click="reviseReply(m)">创建修订版</button></div><button v-if="m.parent_message_id" class="text-button" @click="jumpMessage(m.parent_message_id)">核对原采用版本</button><details v-if="m.draft_history?.length" class="draft-history"><summary>修改与采用记录（{{m.draft_history.length}}）</summary><div v-for="(h,index) in m.draft_history" :key="index"><strong>{{h.action==='adopt'?'采用回复':'保存修改'}} · {{h.actor}} · {{time(h.at)}}</strong><p>{{h.content}}</p></div><details v-if="m.original_content"><summary>最初内容</summary><p>{{m.original_content}}</p></details></details></div></div></article>
        </div>
        <form class="composer" @submit.prevent="send">
          <div class="composer-tabs" role="group" aria-label="输入内容类型"><button v-for="mode in [{id:'customer',label:'客户原话'},{id:'operation',label:'客服操作'},{id:'manual',label:'手写回复'},{id:'note',label:'内部备注'}]" :key="mode.id" type="button" :class="{selected:composerMode===mode.id}" :aria-pressed="composerMode===mode.id" :disabled="busy" @click="composerMode=mode.id">{{mode.label}}</button></div>
          <div v-if="pendingRequest" class="request-recovery" role="status"><strong>{{pendingRequest.state==='running'?'正在生成，输入已保留':pendingRequest.hint||'上次生成尚未确认完成'}}</strong><details><summary>核对本次输入</summary><p>{{pendingRequest.message}}</p></details><div><button type="button" class="secondary" :disabled="busy" @click="performReply(pendingRequest)">{{pendingRequest.state==='failed'?'重试同次生成':'恢复生成状态'}}</button><button type="button" class="text-button" :disabled="busy" @click="composerMode='manual'">改为手写回复</button><button v-if="pendingRequest.state==='failed'" type="button" class="text-button" :disabled="busy" @click="stopRetry">保留原话，停止重试</button></div></div>
          <template v-if="composerMode==='operation'"><div class="staff-tools"><button type="button" class="secondary" :disabled="busy||!selected||!!pendingRequest" @click="staffAction('translate')">翻译原文</button><button type="button" class="secondary" :disabled="busy||!selected||!order||!!pendingRequest" @click="staffAction('order_facts')">核对订单时效</button><button type="button" class="secondary" :disabled="busy||!selected||!!pendingRequest" @click="staffAction('redraft')">重新生成回复</button></div><label for="staff-instruction">给客服助手的操作要求</label><textarea id="staff-instruction" v-model="operationDraft" rows="3" :disabled="busy||!selected" maxlength="12000" placeholder="例如：根据客户原文归纳待核对的问题。这段要求不会作为客户原话保存。" @keydown="key"/></template>
          <template v-else-if="composerMode==='manual'"><p v-if="manualOrigin" class="source-note">从客服参考单独准备的客户回复，请逐句核对后保存。</p><label for="manual-reply">直接撰写客户回复草稿</label><textarea id="manual-reply" v-model="manualDraft" rows="4" :disabled="busy||!selected" maxlength="16000" placeholder="无需调用模型。写好后保存为人工草稿，再核对并采用。" @keydown="key"/></template>
          <template v-else-if="composerMode==='note'"><label for="internal-note">仅供客服查看的内部备注</label><textarea id="internal-note" v-model="noteDraft" rows="3" :disabled="busy||!selected" maxlength="4000" placeholder="记录内部核对结果；不进入模型上下文" @keydown="key"/></template>
          <template v-else><label for="reply">录入客户原话，生成回复草稿</label><textarea id="reply" v-model="draft" rows="3" :disabled="busy||!selected" maxlength="12000" placeholder="只录入客户实际提出的问题；翻译、计算等要求请使用客服操作。" @keydown="key"/></template>
          <div class="composer-submit"><span>{{composerMode==='note'||composerMode==='manual'?'本地保存 · 不调用模型':'输入会保留到结果确认 · Shift + Enter 换行'}}</span><button class="primary" :disabled="busy||!selected||!(composerMode==='note'?noteDraft.trim():composerMode==='manual'?manualDraft.trim():pendingRequest|| (composerMode==='operation'?operationDraft.trim():draft.trim()))">{{busy?'处理中…':composerMode==='note'?'保存内部备注':composerMode==='manual'?'保存人工草稿':pendingRequest?'重试本次生成':composerMode==='operation'?'执行客服操作':'保存原话并生成'}}<UiIcon name="arrow" :size="16"/></button></div>
        </form>
      </div>
      <aside class="context"><section v-if="memory?.customer_message_count" class="memory-panel"><div class="section-heading"><h2>会话要点</h2><span>{{memory.customer_message_count}} 条客户消息</span></div><p class="source-note">客户原文摘录，未经核实；不含内部备注与未采用回复。</p><dl v-if="Object.keys(memory.facts||{}).length"><template v-for="(item,key) in memory.facts" :key="key"><dt>{{({name:'自述姓名',order_id:'提供订单',request:'客户诉求'})[key]}}</dt><dd><button class="memory-source" @click="jumpMessage(item.message_id)">{{item.value}}</button></dd></template></dl><details><summary>核对原文摘录</summary><button v-for="e in memory.excerpts" :key="e.message_id" class="memory-excerpt" @click="jumpMessage(e.message_id)">{{e.content}}</button></details><small class="source-note">要点已保存 · {{time(memory.updated_at)}}</small></section><section><div class="section-heading"><h2>客户与事项</h2><UiIcon name="layers" :size="17"/></div><dl><dt v-if="order">匿名客户标识</dt><dd v-if="order"><code>{{order.customer_id}}</code></dd><dt>工作台用户</dt><dd>{{selected?.user_id||settings.userId}}</dd><dt>负责人</dt><dd>{{selected?.owner||'待分派'}}</dd><dt>会话状态</dt><dd>{{labels[selected?.status]||'尚未创建'}}</dd></dl><small class="muted">当前范围：{{currentSpace?.name||'个人记录'}}。标识切换不是登录认证。</small><button v-if="selected" class="text-button" :disabled="busy" @click="showIntake">补齐受理信息</button><dl v-if="selected?.intake"><dt>问题类型</dt><dd>{{issueLabels[selected.intake.issue_type]}}</dd><template v-for="(label,key) in intakeLabels" :key="key"><dt v-if="selected.intake[key]">{{label}}</dt><dd v-if="selected.intake[key]">{{selected.intake[key]}}</dd></template></dl></section>
        <section><div class="section-heading"><h2>关联订单</h2><span class="subtle-badge">只读</span></div><template v-if="order"><code class="order-id">{{order.display_id||order.id}}</code><div class="order-status">{{orderStatus(order.status)}}<span>{{order.is_demo?'合成演示':'历史快照'}}</span></div><dl><dt>商品与运费合计</dt><dd>{{order.total?.toFixed(2)}} {{order.currency||'BRL'}}</dd><dt>购买日期</dt><dd>{{order.purchased_at?.slice(0,10)}}</dd><dt>预计送达</dt><dd>{{order.estimated_at?.slice(0,10)||'—'}}</dd><dt>实际送达</dt><dd>{{order.delivered_at?.slice(0,10)||'未记录'}}</dd><dt>客户地区</dt><dd>{{order.city}} / {{order.state}}</dd></dl><section v-if="order.items?.length" class="order-group-summary"><h3>按商品汇总 · {{orderGroups.length}} 个标识</h3><article v-for="g in orderGroups" :key="g.product_id"><code>{{g.product_id}}</code><strong>订单记录 {{g.rows}} 行</strong><p>商品合计 {{g.price.toFixed(2)}} {{order.currency||'BRL'}}<br/>运费合计 {{g.freight.toFixed(2)}} {{order.currency||'BRL'}}</p></article><small>订单行数不等于已核验的实收数量；实收情况需结合客户原话与凭证。</small></section><details v-if="order.items?.length" class="order-events"><summary>商品与运费明细（{{order.items.length}}）</summary><ol><li v-for="(item,i) in order.items" :key="i">商品 {{item.product_id}}<br/>商品 {{item.price}} {{order.currency||'BRL'}} · 运费 {{item.freight}} {{order.currency||'BRL'}}</li></ol></details><details class="order-events"><summary>核对订单与反馈时间线</summary><ol><li>购买：{{order.purchased_at}}</li><li v-if="messages.find(m=>m.source_created_at)">评价记录创建：{{messages.find(m=>m.source_created_at).source_review_created_at||messages.find(m=>m.source_created_at).source_created_at}}</li><li v-if="messages.find(m=>m.source_created_at)">客户评价作答：{{messages.find(m=>m.source_created_at).source_answered_at||'源数据未收录'}}</li><li>预计送达：{{order.estimated_at||'未记录'}}</li><li>实际送达：{{order.delivered_at||'未记录'}}</li></ol></details><p class="source-note">{{order.is_demo?'合成演示订单，仅供练习；非真实客户或实时物流。':'Olist 匿名真实历史订单，2016—2018。非当前物流信息。'}}</p></template><p v-else class="muted">尚未关联订单。可查询已导入的 120 条反馈对应订单。</p><form v-if="selected" class="order-search" @submit.prevent="searchOrders"><label for="order-query">查找本地订单</label><div><input id="order-query" v-model="orderQuery" placeholder="订单号或地区"/><button class="secondary" :disabled="busy">查找</button></div></form><div v-if="orderResults.length" class="order-results"><button v-for="o in orderResults.slice(0,8)" :key="o.id" :disabled="busy" @click="linkOrder(o)">{{o.display_id||o.id.slice(0,14)+'…'}}<small>{{o.city}} · {{orderStatus(o.status)}}</small></button></div></section>
        <CaseFollowupPanel ref="followupPanel" v-if="selected" :conversation="selected" :settings="settings" :members="members" @changed="onFollowupChanged"/><section><div class="section-heading"><h2>人工跟进</h2><span>{{conversationTickets.length}}</span></div><button v-for="t in conversationTickets" :key="t.id" class="ticket-link" @click="openTicket(t)"><strong>{{t.id}}</strong><span>{{labels[t.status]}} · {{t.owner}}</span></button><button class="secondary full" :disabled="busy||!selected" @click="createTicket"><UiIcon name="plus" :size="15"/>创建本地工单</button><button class="text-button" :disabled="busy||!selected" @click="createGap">登记知识缺口</button><p class="source-note">保存摘要、负责人和处理记录。未接入真实客服平台，未发送通知或执行退款。</p></section>
      </aside>
    </section>

    <OperationsPanel v-else-if="['todo','report','team','map'].includes(view)" :view="view" :settings="settings" :workspaces="workspaces" :members="members" :initial-filter="operationsFilter" @navigate="navigate" @open-ticket="openTicket" @open-conversation="selectConversation" @workspace-changed="changeWorkspace" @refresh-spaces="loadSpaces" @open-historical="openHistoricalCase"/>
    <section v-else-if="view==='tickets'" class="page"><header class="page-title"><div><h1>工单跟进</h1><p>记录谁在何时完成下一步，结案结果与事项状态同步。</p></div><button class="secondary" :disabled="busy" @click="navigate('todo')">查看到期待办</button></header>
      <div class="split"><div class="list-panel"><button v-for="t in tickets" :key="t.id" class="list-row" :class="{selected:ticket?.id===t.id}" @click="openTicket(t)"><div><strong>{{t.id}}</strong><span class="badge" :class="t.status">{{labels[t.status]}}</span></div><h2>{{t.title}}</h2><p>{{t.next_action||t.summary.slice(0,90)}}</p><small>{{t.owner}} · {{t.due_at?'跟进 '+time(t.due_at):'尚无跟进期限'}}</small></button><p v-if="!tickets.length" class="small-empty">{{listsLoaded?'暂无工单。在会话中创建，或从客户反馈受理。':online?'工单尚未读取，可重新读取当前页面。':'工单尚未读取，连接恢复后会自动加载。'}}</p></div>
        <section v-if="ticket" class="detail-panel ticket-detail"><div class="section-heading"><h2>{{ticket.id}}</h2><button class="text-button" :disabled="busy" @click="selectConversation(ticket.conv_id)">打开关联会话</button></div><p class="muted">{{ticket.scope}}</p><CaseProgress v-if="ticketEdit.status==='resolved'&&ticket.status!=='resolved'" :conversation-id="ticket.conv_id" :ticket-id="ticket.id" :settings="settings" :refresh-token="workflowRevision" expanded @action="goToCaseStep"/><div v-if="ticketDraftConflict" class="draft-conflict" role="alert"><strong>工单记录已更新，未提交草稿已保留。</strong><p>请核对当前处理历史后继续；不会直接覆盖其他人的更新。</p><button class="secondary" type="button" @click="rebaseTicket">已核对当前工单，保留草稿继续编辑</button><button class="text-button" type="button" @click="discardTicketDraft">放弃此工单草稿</button></div><p class="form-draft-note">未提交工单内容会按当前用户和工作范围保留；返回此工单可继续。</p><section v-if="pendingTicketCheck" class="ticket-save-unknown" role="alert"><strong>本次保存结果待确认</strong><p>填写内容已保留。连接恢复不代表保存成功，请先读取当前工单，核对处理历史后再决定下一步。</p><button type="button" class="secondary" :disabled="busy||!online" @click="checkTicketSave">核对保存结果</button></section><h3>事项摘要</h3><p class="summary-text">{{ticket.summary}}</p><p v-if="ticket.order_id" class="source-note">关联订单 {{ticket.order_id}}</p>
          <section v-if="ticket.handoff" class="handoff-panel" :class="ticket.handoff.state"><h3>{{handoffLabels[ticket.handoff.state]||ticket.handoff.state}}</h3><p><strong>当前责任人：</strong>{{ticket.owner}}<br/><strong>接班同事：</strong>{{ticket.handoff.candidate}}<br/><strong>交接说明：</strong>{{ticket.handoff.reason||'见处理历史'}}</p><p v-if="ticket.handoff.decision_note">确认记录：{{ticket.handoff.decision_note}} · {{ticket.handoff.decided_by}} · {{time(ticket.handoff.decided_at)}}</p><template v-if="ticket.handoff.state==='pending'"><p class="source-note">接受前，当前责任人继续跟进；分派不会自动计为已接手。</p><template v-if="ticket.handoff.candidate===settings.userId"><label for="handoff-note">交接核对说明 / 退回原因<textarea id="handoff-note" v-model="handoffNote" rows="2" maxlength="2000" placeholder="接受可填写核对说明；退回必须说明原因"/></label><div class="actions"><button class="primary" :disabled="busy" @click="decideHandoff('accept')">接受交接</button><button class="secondary" :disabled="busy||!handoffNote.trim()" @click="decideHandoff('return')">退回交接</button></div></template></template></section>
          <form v-if="ticket.status!=='resolved'" @submit.prevent="saveTicket"><HandoffChecklist :ticket="ticket" :candidate="ticketEdit.owner" :settings="settings" v-model="ticketEdit.handoff_plan"/><div class="form-row"><label>{{settings.workspaceId?'负责人 / 发起交接':'负责人'}}<select v-if="settings.workspaceId" v-model="ticketEdit.owner" aria-label="工单负责人"><option value="待分派">待分派</option><option v-for="m in members" :key="m.id" :value="m.id">{{m.id}}</option></select><input v-else v-model="ticketEdit.owner" aria-label="工单负责人" required maxlength="200"/></label><label>工单状态<select v-model="ticketEdit.status" aria-label="工单状态"><option value="open">待处理</option><option value="in_progress">处理中</option><option value="pending">待跟进</option><option value="resolved">已解决</option></select></label></div>
            <div class="form-row"><label>优先级<select v-model="ticketEdit.priority" aria-label="工单优先级"><option value="urgent">紧急</option><option value="high">较高</option><option value="normal">普通</option><option value="low">较低</option></select></label><label>跟进截止时间（上海）<input type="datetime-local" v-model="ticketEdit.due_at" aria-label="跟进截止时间"/></label></div>
            <p v-if="settings.workspaceId" class="source-note">选择其他成员并保存后发起交接；对方接受后才切换责任人。</p><label>等待原因<input v-model="ticketEdit.wait_reason" maxlength="200" placeholder="例如：等待仓库核对"/></label><label>下一步行动<textarea v-model="ticketEdit.next_action" rows="2" maxlength="1000" :required="!!ticketEdit.due_at" placeholder="例如：核对缺件数量后，在约定时间回访"/></label><label v-if="ticketEdit.status==='resolved'">结案结果<textarea v-model="ticketEdit.resolution" rows="2" maxlength="2000" required placeholder="写清已核实的结果与未执行的操作"/></label><ClosurePlanForm v-if="ticketEdit.status==='resolved'" :key="ticket.id" v-model="ticketEdit.closure_plan" :conversation-id="ticket.conv_id" :settings="settings" :members="members"/><label>本次处理记录<textarea v-model="ticketEdit.note" rows="3" required maxlength="2000" placeholder="记录交接依据、核对结果或本次进展"/></label><p class="source-note">到期将进入本地待办；未发送外部通知。多人编辑时会检查工单版本。</p><button class="primary" :disabled="busy||!!pendingTicketCheck||ticketDraftConflict||!ticketEdit.note.trim()||!ticketEdit.owner.trim()">保存处理记录</button></form>
          <form v-else @submit.prevent="reopenTicket"><p class="adopted-state">已解决 · {{time(ticket.resolved_at)}}<br/>{{ticket.resolution||'历史结案记录'}}</p><label>重新打开原因<textarea v-model="ticketEdit.note" required maxlength="2000" rows="2" placeholder="例如：客户补充材料，需继续核对"/></label><button class="secondary" :disabled="busy||!ticketEdit.note.trim()">重新打开原工单</button></form>
          <h3>处理历史</h3><ol class="timeline"><li v-for="(h,i) in [...ticket.history].reverse()" :key="i"><div><strong>{{h.actor||h.owner}}</strong><span v-if="h.status">{{labels[h.status]}}</span><time>{{time(h.at)}}</time></div><p>{{h.action}}</p><small v-if="h.owner">负责人 {{h.owner}}</small></li></ol>
        </section><div v-else class="detail-panel empty-detail">选择工单查看交接、期限与处理历史。</div>
      </div>
    </section>

    <section v-else-if="view==='knowledge'" class="page knowledge-page"><header class="page-title"><div><h1>{{currentSpace?.is_demo?'演示规则与知识缺口':'知识文档'}}</h1><p v-if="currentSpace?.is_demo">合成规则仅用于对应案例；可查看缺口与回查记录后回到原对话。</p><p v-if="!currentSpace?.is_demo">{{effectiveDocs.length}} 篇业务已生效 · {{activeDocs.length}} 篇未归档文档，示例与草稿单独用于测试。</p></div><div v-if="!currentSpace?.is_demo" class="actions"><label class="import-scope">上传范围<select v-model="importScope" aria-label="上传文档范围"><option value="business">业务知识（草稿）</option><option value="test">测试资料</option></select></label><label class="secondary upload"><UiIcon name="upload" :size="16"/>上传文件<input type="file" accept=".txt,.md,.json,.pdf,.docx" :disabled="busy" @change="upload"/></label><button class="primary" :disabled="busy" @click="docDialog.showModal()"><UiIcon name="plus" :size="16"/>添加文档</button></div></header><KnowledgeGapPanel :settings="settings" :members="members" :documents="effectiveDocs" @open-conversation="selectConversation" @changed="rechecksPanel?.load()"/><KnowledgeRechecks ref="rechecksPanel" :settings="settings" @open-conversation="selectConversation"/><div v-if="currentSpace?.is_demo" class="demo-policy-list"><button v-for="p in demoPolicies" :key="p.id" :disabled="busy" @click="openDemoPolicy(p.id)">{{p.title}} · 演示 v{{p.version}}<br/><small>只读合成规则 · 点击查看原文与预置流程记录</small></button></div><template v-if="!currentSpace?.is_demo"><p class="format-note">支持 TXT / MD / JSON / 文本 PDF / DOCX。扫描件需先 OCR，暂不支持旧版 DOC。单文件 ≤10MB，PDF ≤200页。索引就绪不代表审核生效。</p><details v-if="imports.length" class="import-history"><summary>最近导入状态 · {{imports[0].status==='ready'?'索引就绪':imports[0].status==='failed'?'导入失败':'建立索引中'}}</summary><ul><li v-for="i in imports.slice(0,10)" :key="i.id"><strong>{{i.filename}}</strong><span>{{i.status==='ready'?'索引就绪':i.status==='failed'?'失败：'+i.error:'建立索引中'}}</span><time>{{time(i.updated_at)}}</time></li></ul></details><form class="knowledge-search" @submit.prevent="search"><label for="knowledge-query">语义检索</label><select v-model="searchMode" aria-label="知识检索模式"><option value="business">已生效业务知识</option><option value="test">草稿 / 示例测试</option></select><div><input id="knowledge-query" v-model="query" placeholder="输入实际业务问题，检查召回片段"/><button class="secondary" :disabled="busy||!query.trim()">检索知识</button></div></form><div v-if="searched" class="search-results"><p v-if="!results.length">当前模式未命中可核对知识。业务模式需要审核生效；测试模式可检查示例和草稿。</p><button v-for="s in results" :key="s.document_id+':'+s.chunk" :disabled="busy" @click="openDoc(s.document_id,s.version)"><strong>{{s.title}} · v{{s.version}}</strong><p>{{previewText(s.content)}}</p><small>{{s.source}} · 片段 {{s.chunk+1}} · 相似度 {{s.score}}</small></button></div><div class="split knowledge-split"><div class="list-panel"><div class="list-filter"><strong>文档目录</strong><label><input v-model="includeArchived" type="checkbox"/>显示归档</label></div><button v-for="d in shownDocs" :key="d.id" class="list-row" :class="{selected:(document?.document_id||document?.id)===d.id}" :disabled="busy" @click="openDoc(d.id)"><div><h2>{{d.title}}</h2><span class="badge" :class="d.deleted?'pending':d.review_status==='approved'?'resolved':d.review_status==='pending'?'pending':'open'">{{d.deleted?'已归档':d.scope==='business'&&d.published_version===d.version?'已生效':reviewLabels[d.review_status||'draft']}}</span></div><p>{{previewText(d.content_preview)}}</p><small>{{scopeLabels[d.scope||'test']}} · v{{d.version}}<span v-if="d.published_version"> / 生效 v{{d.published_version}}</span> · {{d.chunks}} 片段 · {{time(d.updated_at)}}</small></button></div><section v-if="document" class="detail-panel"><div class="section-heading"><h2>文档详情</h2><label class="version-picker">版本<select :value="document.version" aria-label="文档版本" :disabled="busy" @change="changeVersion"><option v-for="v in document.versions" :key="v.version" :value="v.version">v{{v.version}}</option></select></label></div><p class="source-note">{{scopeLabels[document.scope||'test']}} · {{reviewLabels[document.review_status||'draft']}}<br>来源：{{document.source}}<br>更新：{{time(document.updated_at)}} · 当前版本 v{{document.current_version}}<span v-if="document.archived"> · 已归档，不参与检索</span></p><p v-if="document.version!==document.current_version" class="history-warning">正在核对历史版本。请选择当前版本进行编辑。</p><p v-if="document.current_published_version&&document.current_published_version!==document.current_version" class="history-warning">新版尚未生效，业务模式继续使用 v{{document.current_published_version}}。</p><form @submit.prevent="saveDoc"><label>文档范围<select v-model="editor.scope" aria-label="文档范围" :disabled="busy||document.version!==document.current_version||document.archived"><option value="business">业务知识（需审核生效）</option><option value="test">测试资料（不进入业务模式）</option></select></label><label>文档标题<input v-model="editor.title" :readonly="document.version!==document.current_version||document.archived" required/></label><label>完整正文<textarea v-model="editor.content" rows="9" :readonly="document.version!==document.current_version||document.archived" required/></label><div class="actions"><button v-if="!document.archived" class="primary" :disabled="busy||document.version!==document.current_version||!editor.title.trim()||!editor.content.trim()">保存为新草稿</button><button v-if="!document.archived" type="button" class="secondary danger" :disabled="busy" @click="archiveDoc">归档文档（可恢复）</button><button v-else type="button" class="primary" :disabled="busy" @click="restoreDoc">恢复为草稿</button></div></form><section v-if="!document.archived&&document.version===document.current_version" class="document-review"><h3>本地审核</h3><p class="source-note">记录审核人和理由。测试资料审核后仍不会进入业务模式；此记录不代表企业账号授权。</p><label for="review-note">审核说明<textarea id="review-note" v-model="reviewNote" rows="2" maxlength="2000" placeholder="填写提交原因、审核结论或退回原因"/></label><p v-if="documentDirty" class="form-error">正文或范围尚未保存，请先保存草稿再审核。</p><div class="actions"><button v-if="document.review_status==='draft'" type="button" class="secondary" :disabled="busy||documentDirty||!reviewNote.trim()" @click="reviewDoc('submit')">提交审核</button><template v-if="document.review_status==='pending'"><button type="button" class="primary" :disabled="busy||documentDirty||!reviewNote.trim()" @click="reviewDoc('approve')">{{document.scope==='business'?'审核通过并生效':'审核通过（仅测试）'}}</button><button type="button" class="secondary danger" :disabled="busy||documentDirty||!reviewNote.trim()" @click="reviewDoc('reject')">退回草稿</button></template><p v-if="document.review_status==='approved'" class="adopted-state">{{document.scope==='business'?'此版本已生效；修改将生成新的待审草稿。':'此版本已审核，范围仍为测试。'}}</p></div></section><details v-if="document.review_history?.length" class="review-history"><summary>审核历史（{{document.review_history.length}}）</summary><div v-for="(h,index) in [...document.review_history].reverse()" :key="index"><strong>v{{h.version}} · {{({submit:'提交审核',approve:'审核通过',reject:'退回草稿'})[h.action]}} · {{h.actor}}</strong><p>{{h.note}}</p><time>{{time(h.at)}}</time></div></details></section><div v-else class="detail-panel empty-detail">选择文档查看完整内容、编辑版本或恢复归档。</div></div></template></section>

    <section v-else-if="view==='feedback'" class="page"><header class="page-title"><div><h1>客户反馈</h1><p>真实历史评价形成待处理事项，原文、订单和处理记录相互关联。</p></div><span class="scope-tag">Olist 历史样本</span></header><div class="dataset-banner"><div><strong>{{dataset?.imported_reviews||0}} 条真实评价 / {{dataset?.imported_orders||0}} 笔关联订单</strong><p>{{dataset?.filter}}。保留葡萄牙语原文；点击“查看中文译文”即可对照阅读。导入未调用模型。</p></div><a :href="dataset?.source_url" target="_blank" rel="noreferrer">数据来源 ↗</a></div><p class="source-note">2016—2018 · BRL · CC BY-NC-SA 4.0 · 匿名历史反馈，不是企业政策或实时投诉。</p><label class="searchbox feedback-search"><UiIcon name="search" :size="17"/><input v-model="feedbackQuery" aria-label="筛选客户反馈" placeholder="搜索评价原文或订单号"/></label><div class="feedback-table"><div class="feedback-table-head"><span>客户原文 / 关联订单</span><span>评分与日期</span><span>处理入口</span></div><article v-for="r in shownFeedback" :key="r.id"><div><h2 v-if="r.title">{{r.title}}</h2><p lang="pt-BR">{{r.content}}</p><ReviewTranslation :review-id="r.id" :source-text="r.content" :settings="settings"/><code>{{r.order_id}}</code></div><div><span class="rating">{{r.score}} / 5 分</span><small>记录创建 {{(r.review_creation_date||r.created_at).slice(0,10)}}<br/>客户作答 {{r.review_answer_timestamp||'未收录'}}</small></div><button class="secondary" :disabled="busy" @click="feedbackCase(r)">{{conversations.some(c=>c.review_id===r.id)?'打开已有事项':'受理反馈'}}</button></article></div></section>

    <MonitorPanel v-else :key="settings.userId+':'+settings.backend" :settings="settings" @open-example="openDemoCase"/>
  </main>
  <dialog ref="demoPolicyDialog" class="demo-policy-modal" aria-labelledby="demo-policy-title"><div v-if="demoPolicy"><header><h2 id="demo-policy-title">{{demoPolicy.title}} · v{{demoPolicy.version}}</h2><button class="icon" aria-label="关闭演示规则" @click="demoPolicyDialog.close()">×</button></header><p class="source-note">合成演示规则 · 仅当前对应案例使用 · 只读</p><MarkdownContent :markdown="demoPolicy.content"/><details><summary>预置流程记录</summary><ul><li v-for="(h,i) in demoPolicy.review_history" :key="i">{{h.actor}} · {{h.action}} · {{h.note}}</li></ul></details><button class="secondary" @click="demoPolicyDialog.close()">返回原会话</button></div></dialog>
  <dialog ref="identityDialog"><form @submit.prevent="applyIdentity"><header><h2>切换工作台用户</h2><button type="button" class="icon" aria-label="关闭用户设置" @click="identityDialog.close()">×</button></header><label>用户标识<input v-model="identity" required maxlength="200"/></label><p class="muted">个人范围按此标识隔离；加入协作空间后可查看该空间共享事项。知识和只读历史数据在本机共享。此功能不是账号认证。</p><button class="primary" :disabled="busy||!identity.trim()">应用用户标识</button></form></dialog>
  <dialog ref="closureDialog"><form @submit.prevent="closeCase"><header><h2>确认事项结案结果</h2><button type="button" class="icon" aria-label="关闭结案" @click="closureDialog.close()">×</button></header><p class="muted">先处理下方欠缺条件，再记录结案结果。采用回复不等于问题已解决。</p><CaseProgress ref="closureChecks" v-if="selected" :conversation-id="selected.id" :settings="settings" :refresh-token="workflowRevision" expanded @action="goToCaseStep"/><label>解决结果<textarea v-model.trim="closureReason" required maxlength="2000" rows="4"/></label><ClosurePlanForm v-if="selected" :key="selected.id" :refresh-token="workflowRevision" :conversation-id="selected.id" :settings="settings" :members="members" v-model="closurePlan"/><p v-if="failed&&notice" id="case-close-error" tabindex="-1" class="form-error" role="alert">{{notice}}</p><button class="primary" :disabled="busy||!closureReason">记录结果并结案</button></form></dialog>
  <dialog ref="intakeDialog"><form @submit.prevent="saveIntake"><p class="form-draft-note" role="status">{{intakeDraftNotice}}</p><header><h2>补齐受理信息</h2><button type="button" class="icon" aria-label="关闭受理信息" @click="intakeDialog.close()">×</button></header><label>问题类型<select v-model="intake.issue_type"><option v-for="(label,key) in issueLabels" :key="key" :value="key">{{label}}</option></select></label><label>涉及商品标识<input v-model="intake.product_id" maxlength="200"/></label><label>涉及数量<input type="number" min="1" max="999" v-model="intake.quantity"/></label><label>客户期望结果<textarea v-model="intake.desired_outcome" rows="2" maxlength="1000"/></label><label>材料与证据说明<textarea v-model="intake.evidence_note" rows="2" maxlength="2000" placeholder="记录已收到及仍缺少的材料；原文件可在右侧“结果与材料 → 材料追补”上传"/></label><p v-if="failed&&notice" class="form-error">{{notice}}</p><button class="primary" :disabled="busy">保存受理信息</button></form></dialog>
  <dialog ref="docDialog"><form @submit.prevent="addDoc"><header><h2>添加业务文档</h2><button class="icon" type="button" aria-label="关闭添加文档" @click="docDialog.close()">×</button></header><label>文档标题<input v-model="newDoc.title" required maxlength="200"/></label><label>文档范围<select v-model="newDoc.scope" aria-label="新文档范围"><option value="business">业务知识（保存为待审草稿）</option><option value="test">测试资料</option></select></label><label>文档正文<textarea v-model="newDoc.content" rows="10" required/></label><p class="muted">保存后建立检索索引。请标明是否为测试内容；客户评价不应作为客服政策。</p><p v-if="failed&&notice" class="form-error" role="alert">{{notice}}</p><button class="primary" :disabled="busy||!newDoc.title.trim()||!newDoc.content.trim()">{{busy?'正在建立索引…':'保存并建立索引'}}</button></form></dialog>
</div>
</template>
